/**
 * BOJ 14567 선수과목: https://www.acmicpc.net/problem/14567
 *
 * 입력: N M 다음에 선수 조건 A B가 M줄 주어진다. 테스트 케이스 수 T는 없다.
 * 출력: 1번부터 N번 과목까지 이수 가능한 최소 학기를 공백으로 구분한다.
 * 모든 과목은 매 학기 개설되고 수강 개수 제한이 없다. A < B이므로 순환은 없다.
 *
 * 핵심 풀이: 진입 차수가 0인 과목부터 위상 정렬한다. 선수과목이 없는 과목은
 * 1학기이고, 나머지는 모든 선수과목의 최소 학기 중 최댓값에 1을 더한다.
 * 진입 차수가 0이 되는 순간에는 모든 선수과목의 학기가 반영되어 있다.
 * 시간 복잡도 O(N + M), 공간 복잡도 O(N + M).
 * BOJ 제출 시 public class 이름을 Main으로 바꾼다.
 */
public class 선수과목 {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());

        List<List<Integer>> nextSubjects = new ArrayList<>();
        for (int subject = 0; subject <= n; subject++) {
            nextSubjects.add(new ArrayList<Integer>());
        }
        int[] indegree = new int[n + 1];
        for (int i = 0; i < m; i++) {
            st = new StringTokenizer(br.readLine());
            int prerequisite = Integer.parseInt(st.nextToken());
            int next = Integer.parseInt(st.nextToken());
            nextSubjects.get(prerequisite).add(next);
            indegree[next]++;
        }

        int[] semester = new int[n + 1];
        Arrays.fill(semester, 1);
        Queue<Integer> queue = new ArrayDeque<>();
        for (int subject = 1; subject <= n; subject++) {
            if (indegree[subject] == 0) {
                queue.offer(subject);
            }
        }

        while (!queue.isEmpty()) {
            int current = queue.poll();
            for (int next : nextSubjects.get(current)) {
                semester[next] = Math.max(semester[next], semester[current] + 1);
                if (--indegree[next] == 0) {
                    queue.offer(next);
                }
            }
        }

        StringBuilder answer = new StringBuilder();
        for (int subject = 1; subject <= n; subject++) {
            if (subject > 1) {
                answer.append(' ');
            }
            answer.append(semester[subject]);
        }
        System.out.println(answer);
    }
}

import java.util.*;
import java.io.*;

public class 프로세서연결하기 {

    static class Core {
        int r;
        int c;

        Core(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    static final int[] dr = { 0, 1, 0, -1 };
    static final int[] dc = { 1, 0, -1, 0 };

    static List<Core> cores;
    static int[][] map;
    static int maxConnected;
    static int minLength;
    static int N;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();
        StringTokenizer st;

        int T = Integer.parseInt(br.readLine().trim());
        for (int tc = 1; tc <= T; tc++) {
            sb.append('#').append(tc).append(' ');
            N = Integer.parseInt(br.readLine().trim());

            maxConnected = 0;
            minLength = 145;
            cores = new ArrayList<>();
            map = new int[N][N];
            for (int i = 0; i < N; i++) {
                st = new StringTokenizer(br.readLine());
                for (int j = 0; j < N; j++) {
                    map[i][j] = Integer.parseInt(st.nextToken());
                    if (map[i][j] == 1) {
                        if (i != 0 && i != N - 1 && j != 0 && j != N - 1) {
                            cores.add(new Core(i, j));
                        }
                    } // if end
                } // for j end
            } // for i end

            dfs(0, 0, 0);
            sb.append(minLength).append('\n');
        } // tc end
        System.out.print(sb);
    } // main end

    static void dfs(int depth, int cntConn, int lengthSum) {
        if (cntConn + cores.size() - depth < maxConnected) {
            return;
        }

        if (depth == cores.size()) {
            if (maxConnected < cntConn) {
                maxConnected = cntConn;
                minLength = lengthSum;
            } else if (maxConnected == cntConn) {
                if (minLength > lengthSum)
                    minLength = lengthSum;
            }

            return;
        }

        Core cur = cores.get(depth);

        for (int dir = 0; dir < 4; dir++) {
            if (canConnect(cur, dir)) {
                int len = setWire(cur, dir, 1);
                dfs(depth + 1, cntConn + 1, lengthSum + len);
                setWire(cur, dir, 0);
            }
        }

        dfs(depth + 1, cntConn, lengthSum);

    } // dfs end

    static boolean canConnect(Core core, int dir) {
        int nr = core.r + dr[dir];
        int nc = core.c + dc[dir];

        while (inRange(nr, nc)) {
            if (map[nr][nc] != 0) {
                return false;
            }
            nr += dr[dir];
            nc += dc[dir];
        }

        return true;
    }

    static int setWire(Core core, int dir, int value) {
        int length = 0;
        int nr = core.r + dr[dir];
        int nc = core.c + dc[dir];

        while (inRange(nr, nc)) {
            map[nr][nc] = value;
            length++;

            nr += dr[dir];
            nc += dc[dir];
        }
        return length;
    } // setWire

    static boolean inRange(int nr, int nc) {
        return 0 <= nr && nr < N && 0 <= nc && nc < N;
    }
}

import java.io.*;
import java.util.*;

/**
 * BOJ 17471 게리맨더링: https://www.acmicpc.net/problem/17471
 *
 * 입력: 구역 수 N(2~10), 각 구역의 인구, 각 구역의 인접 구역 목록이다.
 * 테스트 케이스 수 T는 없다. 인접 관계는 양방향이다.
 * 출력: 두 선거구의 인구 차이 최솟값. 가능한 분할이 없으면 -1을 출력한다.
 * 두 선거구는 모두 비어 있지 않아야 하고, 각 선거구 안에서 서로 연결되어야 한다.
 *
 * 핵심 풀이: 비트마스크로 첫 선거구를 고르면 나머지는 두 번째 선거구다.
 * 1번 구역을 첫 선거구에 고정해 같은 분할을 두 번 검사하지 않는다.
 * 두 선거구 각각의 연결성을 확인한 뒤에만 인구 차이를 비교한다.
 * 인접 목록도 비트마스크이므로 연결성 검사는 O(N)이다.
 * 시간 복잡도 O(2^N * N), 공간 복잡도 O(N).
 * BOJ 제출 시 public class 이름을 Main으로 바꾼다.
 */
public class 지역구나누기 {
    private static int[] adjacent;

    private static boolean isConnected(int group) {
        int frontier = Integer.lowestOneBit(group);
        int visited = frontier;
        while (frontier != 0) {
            int currentBit = Integer.lowestOneBit(frontier);
            frontier ^= currentBit;
            int current = Integer.numberOfTrailingZeros(currentBit);
            int unvisitedNeighbors = adjacent[current] & group & ~visited;
            visited |= unvisitedNeighbors;
            frontier |= unvisitedNeighbors;
        }
        return visited == group;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        int[] population = new int[n];
        int totalPopulation = 0;
        StringTokenizer st = new StringTokenizer(br.readLine());
        for (int district = 0; district < n; district++) {
            population[district] = Integer.parseInt(st.nextToken());
            totalPopulation += population[district];
        }

        adjacent = new int[n];
        for (int district = 0; district < n; district++) {
            st = new StringTokenizer(br.readLine());
            int count = Integer.parseInt(st.nextToken());
            for (int i = 0; i < count; i++) {
                int neighbor = Integer.parseInt(st.nextToken()) - 1;
                adjacent[district] |= 1 << neighbor;
            }
        }

        int allDistricts = (1 << n) - 1;
        int answer = Integer.MAX_VALUE;
        // 홀수 마스크에는 항상 1번 구역이 들어 있다. 전체 집합은 제외한다.
        for (int group = 1; group < allDistricts; group += 2) {
            int otherGroup = allDistricts ^ group;
            if (!isConnected(group) || !isConnected(otherGroup)) {
                continue;
            }

            int groupPopulation = 0;
            for (int district = 0; district < n; district++) {
                if ((group & (1 << district)) != 0) {
                    groupPopulation += population[district];
                }
            }
            answer = Math.min(answer, Math.abs(2 * groupPopulation - totalPopulation));
            if (answer == 0) {
                break;
            }
        }

        System.out.println(answer == Integer.MAX_VALUE ? -1 : answer);
    }
}

